begin;
create schema domain_handoff_test;
create function domain_handoff_test.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'ok - domain handoff: %',label;end$$;
create function domain_handoff_test.fails(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then raise notice 'ok - domain handoff: % (refused)',label;return;end;raise exception 'FAIL: % was permitted',label;end$$;
grant usage on schema domain_handoff_test to authenticated,anon,service_role;grant execute on all functions in schema domain_handoff_test to authenticated,anon,service_role;
insert into auth.users(id,email) values('dc000000-0000-4000-8000-000000000001','domain-owner@example.test'),('dc000000-0000-4000-8000-000000000002','domain-other@example.test'),('dc000000-0000-4000-8000-000000000003','domain-member@example.test');
insert into public.organizations(id,name,slug) values('dc000000-0000-4000-8000-000000000011','Domain A','domain-a'),('dc000000-0000-4000-8000-000000000012','Domain B','domain-b');
insert into public.organization_members(organization_id,user_id,role,status) values('dc000000-0000-4000-8000-000000000011','dc000000-0000-4000-8000-000000000001','owner','active'),('dc000000-0000-4000-8000-000000000012','dc000000-0000-4000-8000-000000000002','owner','active'),('dc000000-0000-4000-8000-000000000011','dc000000-0000-4000-8000-000000000003','member','active');
insert into public.websites(id,organization_id,name) values('dc000000-0000-4000-8000-000000000021','dc000000-0000-4000-8000-000000000011','Domain fixture'),('dc000000-0000-4000-8000-000000000022','dc000000-0000-4000-8000-000000000012','Other fixture');
create function domain_handoff_test.save(name text,version integer,action text default 'handoff',actor uuid default 'dc000000-0000-4000-8000-000000000001',website uuid default 'dc000000-0000-4000-8000-000000000021',quoted timestamptz default now()) returns public.domain_purchase_intents language sql as $$select public.save_domain_handoff('dc000000-0000-4000-8000-000000000011',website,actor,version,name,jsonb_build_object('hostname',name,'available',true,'currency','USD'),quoted,action)$$;

grant execute on all functions in schema domain_handoff_test to authenticated,anon,service_role;
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select domain_handoff_test.ok((domain_handoff_test.save('vigil-handoff-fixture.com',0)).version=1,'initial handoff persisted');
select domain_handoff_test.ok((domain_handoff_test.save('vigil-handoff-fixture.com',0)).version=1,'lost response / repeated Continue is idempotent');
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',0)$q$,'stale concurrent replacement rejected');
select domain_handoff_test.ok((domain_handoff_test.save('other.com',1)).version=2,'replace unverified selection with CAS');
select domain_handoff_test.fails($q$select domain_handoff_test.save('vigil-handoff-fixture.com',1,'help')$q$,'stale operation rejected');
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',2,'handoff','dc000000-0000-4000-8000-000000000003')$q$,'member cannot mutate');
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',2,'handoff','dc000000-0000-4000-8000-000000000002')$q$,'wrong org actor rejected');
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',2,'handoff','dc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000022')$q$,'wrong website rejected');
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',2,'handoff','dc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000021',now()-interval '1 hour')$q$,'stale quote rejected');
select domain_handoff_test.ok((domain_handoff_test.save('other.com',2,'help')).phase='action_required','unsupported automation honestly records action required');
select domain_handoff_test.ok((domain_handoff_test.save('other.com',3,'cancel')).phase='cancelled','abandonment is durable');
select domain_handoff_test.ok((select count(*)=1 from public.domain_purchase_intents),'one intent per website');
select domain_handoff_test.ok((select count(*)=0 from public.domains where organization_id='dc000000-0000-4000-8000-000000000011'),'handoff never asserts ownership');
select domain_handoff_test.ok((select count(*)=0 from public.provisioning_jobs where organization_id='dc000000-0000-4000-8000-000000000011'),'handoff never enqueues connection or launch');
reset role;
insert into public.organization_members(organization_id,user_id,role,status) values('dc000000-0000-4000-8000-000000000011','dc000000-0000-4000-8000-000000000003','owner','active') on conflict(organization_id,user_id) do update set role='owner';
update public.organization_members set status='suspended' where user_id='dc000000-0000-4000-8000-000000000001';
set local role service_role;
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',4)$q$,'revoked membership rechecked by service-role mutation');
reset role;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"dc000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select domain_handoff_test.ok((select count(*)=0 from public.domain_purchase_intents),'cross-tenant RLS hides selections');
select domain_handoff_test.fails($q$select domain_handoff_test.save('other.com',4)$q$,'authenticated cannot invoke privileged mutation');
select domain_handoff_test.fails($q$update public.domain_purchase_intents set phase='handoff_started'$q$,'customer cannot forge state');
reset role;
set local role anon;select set_config('request.jwt.claims','{"role":"anon"}',true);
select domain_handoff_test.fails($q$select * from public.domain_purchase_intents$q$,'anonymous has no access');
reset role;
rollback;
